-- 570: Foundation guard for WASSCE English Language sprint 3 beta batch (wassce-english-sprint3-001).
-- Original BrillaPrep practice content; not official WAEC examination material.
-- Re-asserts the prod-canonical topic rows for subj_wassce_english on scratch
-- baselines; INSERT OR IGNORE no-ops on prod and on fresh baselines where the
-- rows already exist (prod patch 096 and migrations 363 and 422).
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_eng_cmp', 'subj_wassce_english', NULL, 'Comprehension', 'wassce-p2-eng-cmp', 'Read an unseen passage closely and answer literal, inferential and vocabulary questions on it.', 'Comprehension questions test close reading: literal recall, inference, and the meaning of words and expressions as used in a passage.', '["Main idea vs supporting detail", "Inference = conclusion from evidence", "Vocabulary in context"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_eng_ess', 'subj_wassce_english', NULL, 'Essay writing', 'wassce-p2-eng-ess', 'Compose sustained, well-organized essays in the register and format each essay type demands.', 'Essay writing covers the four main WASSCE types: narrative, descriptive, expository and argumentative, each with its own purpose and register.', '["Narrative = story", "Descriptive = senses", "Expository = explain", "Argumentative = persuade"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_eng_sum', 'subj_wassce_english', NULL, 'Summary writing', 'wassce-p2-eng-sum', 'Distil a passage into concise sentences that capture the required points without distortion.', 'Summary writing requires identifying the main points of a passage and expressing them briefly in the candidate''s own words, without lifting phrases.', '["Own words, no lifting", "One sentence where required", "Main points only"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_summary', 'subj_wassce_english', NULL, 'Summary Writing', 'wassce-english-summary', 'Identifying topic sentences and condensing passages into concise sentences', 'Summary answers keep only the required substance: repetitions, examples and decorative detail are trimmed, and the question''s sentence limit is obeyed.', '["Own words, no lifting", "Obey the sentence limit", "Main points only"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_essay', 'subj_wassce_english', NULL, 'Essay Writing', 'wassce-english-essay', 'Narrative, descriptive, expository and argumentative essays', 'Strong essays are planned: a thesis-driven introduction, body paragraphs of one main idea each linked by transitions, and a decisive conclusion.', '["Plan before writing", "One main idea per paragraph", "Formal register: no contractions or slang"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_letter', 'subj_wassce_english', NULL, 'Letter and Report Writing', 'wassce-english-letter', 'Formal and informal letters, reports, articles and speeches', 'Letter and report writing tests format and register: addresses, salutations, headings, subscriptions, and the impersonal structure of official reports.', '["Formal: two addresses + heading", "Yours faithfully pairs with Dear Sir/Madam", "Reports: title, sections, facts"]', 6, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_lexis', 'subj_wassce_english', NULL, 'Lexis and Structure', 'wassce-english-lexis', 'Vocabulary, collocations, sentence structure and completion items', 'Lexis and structure items test vocabulary in context: nearest and opposite meanings, collocations and the particles of phrasal verbs.', '["Synonym = nearest in meaning", "Antonym = opposite in meaning", "Phrasal verb = verb + particle"]', 7, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_grammar', 'subj_wassce_english', NULL, 'Grammar and Usage', 'wassce-english-grammar', 'Parts of speech, concord, tenses, active and passive voice', 'Grammar and usage covers concord, tense sequence, voice, and the correction and transformation of sentences.', '["Singular subject takes singular verb", "Past perfect for the earlier of two past actions", "Passive: object becomes subject"]', 8, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_oral', 'subj_wassce_english', NULL, 'Oral English', 'wassce-english-oral', 'Vowels, consonants, stress, rhythm and intonation (Test of Orals)', 'Oral English tests the sound system: counting syllables, placing word stress, and reading meaning from rising and falling intonation.', '["Syllable = one vowel sound", "Two-syllable verbs often stress the second syllable", "Rising intonation signals a yes-no question"]', 9, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_english_literary_devices', 'subj_wassce_english', NULL, 'Literary Devices', 'wassce-english-literary-devices', 'Metaphor, simile, personification, hyperbole, alliteration and irony', 'Literary devices are figures of speech and sound patterns writers use for effect; candidates must identify and interpret them in context.', '["Simile uses like/as", "Metaphor states identity", "Personification gives human qualities", "Onomatopoeia imitates sound"]', 10, '2026-08-04T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_570_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_570_guard;
INSERT INTO _migration_570_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'exam_wassce') AND EXISTS (SELECT 1 FROM subjects WHERE id = 'subj_wassce_english' AND exam_type_id = 'exam_wassce') AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_wassce_p2_eng_cmp', 'topic_wassce_p2_eng_ess', 'topic_wassce_p2_eng_sum', 'topic_wassce_english_summary', 'topic_wassce_english_essay', 'topic_wassce_english_letter', 'topic_wassce_english_lexis', 'topic_wassce_english_grammar', 'topic_wassce_english_oral', 'topic_wassce_english_literary_devices') AND t.subject_id = 'subj_wassce_english' AND s.exam_type_id = 'exam_wassce') = 10 THEN 1 ELSE 0 END;
DROP TABLE _migration_570_guard;
